import json, random, sys, subprocess
sys.path.insert(0,'.')
from h2 import *
random.seed(12345)

FRAGS = ['', ' ', '\t', '<', '>', '"', '\\', ';', ',', '=', '@', ':', 'sip:', 'tel:', '+', '%41', '%zz', '%',
         'sip:a@x.test', 'tel:+15550001', 'sip:anonymous@anonymous.invalid', 'tag', 'tag=t1', 'tag=',
         'From', 'To', 'Call-ID', 'CSeq', 'Content-Length', 'Content-Type', 'P-Asserted-Identity',
         'P-Preferred-Identity', 'Remote-Party-ID', 'Privacy', 'f', 't', 'i', 'l', 'c', 'X-Z', '1',
         'MESSAGE', 'INVITE', 'SIP/2.0', 'id', 'none', 'Bob', '"Qu, ote\\""', 'anonymous', 'x.test',
         'a@b@c', '9999999999999', '-1', '.x', 'x.', 'a..b', '[::1]', 'sip:A@X.TEST', '\r\n', '\r\n\r\n']

def rnd_request():
    n = random.randint(0, 12)
    parts = []
    for _ in range(n):
        parts.append(random.choice(FRAGS))
    sep = random.choice(['\r\n', '\r\n', '\r\n', '\n', '\r', '\t', ' '])
    text = sep.join(parts)
    if random.random() < 0.85:
        text += '\r\n\r\n' + random.choice(['hi', '', 'x'*random.randint(1,50), 'a\r\nb', '\t'])
    if random.random() < 0.1:
        text = text[:len(text)//2] + '\x00' + text[len(text)//2:]
    return text

bad = 0
for trial in range(4000):
    jobs = []
    kinds = ['local','peer','untrusted']
    for k in range(random.randint(1,4)):
        kind = random.choice(kinds)
        if random.random() < 0.75:
            j = {'gateway': random.choice(['edge','far','any','none']), 'trusted_out': random.random()<0.5}
            if kind == 'local':
                j['ingress'] = {'kind':'local','subject':random.choice(['s1','s2','ghost'])}
            elif kind == 'peer':
                j['ingress'] = {'kind':'peer','name':random.choice(['edge','ghost'])}
            else:
                j['ingress'] = {'kind':'untrusted'}
            j['raw'] = rnd_request()
        else:
            j = {'gateway': random.choice(['edge','far','any','none']), 'trusted_out': random.random()<0.5,
                 'ingress': {'kind': random.choice(kinds)}, 'source': random.randint(0,3)}
        jobs.append(j)
    out = run(batch(jobs))
    if set(out.keys()) != {'results'}:
        print('BAD KEYS', out); bad += 1; break
    for i, r in enumerate(out['results']):
        if r.get('status') == 'reject':
            if set(r.keys()) != {'status','reason'} or r['reason'] not in ('upstream','syntax','unauthenticated','identity'):
                print('BAD REJECT', i, r); bad += 1
        elif r.get('status') == 'accept':
            if set(r.keys()) != {'status','identity','basis','private','wire'}:
                print('BAD ACCEPT KEYS', i, r); bad += 1
            elif r['basis'] not in ('local','peer') or type(r['private']) is not bool:
                print('BAD ACCEPT VALS', i, r); bad += 1
            elif r['identity'] not in DIR:
                print('BAD IDENTITY', i, r); bad += 1
        else:
            print('BAD STATUS', i, r); bad += 1
    if bad:
        print(json.dumps(batch(jobs))[:600]); break
print('done, bad =', bad)
